-- Approved local R2 ceremony candidate33, outside active migration manifests.
-- Canonical runner owns BEGIN/COMMIT and inserts ledger33 atomically if later operationally authorized.
-- No actor creation, no grant DML, no historical INSERT claim. Before.present is true.
SET LOCAL lock_timeout='5s';
LOCK TABLE iam.roles,iam.permissions,iam.role_permissions IN SHARE ROW EXCLUSIVE MODE;
DO $pre$ DECLARE actor uuid; BEGIN
 actor:=nullif(current_setting('tcdx.publication_service_principal_id',true),'')::uuid;
 IF actor IS NULL OR NOT EXISTS(SELECT 1 FROM iam.service_principals WHERE service_principal_id=actor AND ownership_class='PLATFORM_CONTROL' AND tenant_id IS NULL AND lifecycle_state='active') THEN RAISE EXCEPTION 'STEP6A3_PUBLICATION_ACTOR_REQUIRED';END IF;
 IF NOT EXISTS(SELECT 1 FROM platform.schema_migrations WHERE migration_id='20261009000200' AND content_sha256='920ececb9d28e3821a9faf9d2c754db481a26c0e33c53ae0f94b3a0535885ed8' AND outcome='applied') THEN RAISE EXCEPTION 'STEP6A3_PUBLICATION_SOURCE_REQUIRED';END IF;
 IF (SELECT count(*) FROM iam.role_permissions rp JOIN iam.roles r USING(role_id) JOIN iam.permissions p USING(permission_id) WHERE rp.tenant_id IS NULL AND p.permission_code IN('compliance.framework.read','platform.membership_reference.read','privacy.retention_policy_reference.read'))<>44 THEN RAISE EXCEPTION 'STEP6A3_PUBLICATION_EXACT_SET_REQUIRED';END IF;
 IF EXISTS(SELECT 1 FROM iam.role_permissions rp JOIN iam.roles r USING(role_id) JOIN iam.permissions p USING(permission_id) WHERE p.permission_code IN('compliance.framework.read','platform.membership_reference.read','privacy.retention_policy_reference.read') AND (NOT r.is_baseline OR r.lifecycle_state<>'published' OR rp.tenant_id IS DISTINCT FROM r.tenant_id OR rp.ownership_class<>r.ownership_class OR NOT EXISTS(SELECT 1 FROM(VALUES('EXECUTIVE_BOARD_VIEWER','compliance.framework.read'),('EXECUTIVE_BOARD_VIEWER','platform.membership_reference.read'),('EXECUTIVE_BOARD_VIEWER','privacy.retention_policy_reference.read'),('GRC_MANAGER','compliance.framework.read'),('GRC_MANAGER','platform.membership_reference.read'),('GRC_MANAGER','privacy.retention_policy_reference.read'),('QUALITY_MANAGER','compliance.framework.read'),('QUALITY_MANAGER','platform.membership_reference.read'),('QUALITY_MANAGER','privacy.retention_policy_reference.read'),('COMPLIANCE_MANAGER','compliance.framework.read'),('COMPLIANCE_MANAGER','platform.membership_reference.read'),('COMPLIANCE_MANAGER','privacy.retention_policy_reference.read'),('RISK_MANAGER','platform.membership_reference.read'),('CISO_SECURITY_MANAGER','compliance.framework.read'),('CISO_SECURITY_MANAGER','platform.membership_reference.read'),('CISO_SECURITY_MANAGER','privacy.retention_policy_reference.read'),('AI_GOVERNANCE_MANAGER','compliance.framework.read'),('AI_GOVERNANCE_MANAGER','platform.membership_reference.read'),('AI_GOVERNANCE_MANAGER','privacy.retention_policy_reference.read'),('PRIVACY_MANAGER','compliance.framework.read'),('PRIVACY_MANAGER','platform.membership_reference.read'),('PRIVACY_MANAGER','privacy.retention_policy_reference.read'),('LEGAL_REVIEWER','compliance.framework.read'),('LEGAL_REVIEWER','platform.membership_reference.read'),('LEGAL_REVIEWER','privacy.retention_policy_reference.read'),('AUDITOR_LEAD','compliance.framework.read'),('AUDITOR_LEAD','platform.membership_reference.read'),('AUDITOR_LEAD','privacy.retention_policy_reference.read'),('AUDITOR','compliance.framework.read'),('AUDITOR','platform.membership_reference.read'),('AUDITOR','privacy.retention_policy_reference.read'),('PROCESS_OWNER','platform.membership_reference.read'),('CONTROL_OWNER','platform.membership_reference.read'),('CONTROL_OWNER','privacy.retention_policy_reference.read'),('EVIDENCE_OWNER','platform.membership_reference.read'),('EVIDENCE_OWNER','privacy.retention_policy_reference.read'),('ACTION_OWNER','platform.membership_reference.read'),('REGULATORY_CONTENT_STEWARD','compliance.framework.read'),('REPORT_VIEWER','compliance.framework.read'),('REPORT_VIEWER','platform.membership_reference.read'),('REPORT_VIEWER','privacy.retention_policy_reference.read'),('VIEWER','compliance.framework.read'),('VIEWER','platform.membership_reference.read'),('VIEWER','privacy.retention_policy_reference.read')) e(role_code,permission_code) WHERE e.role_code=r.role_code AND e.permission_code=p.permission_code))) THEN RAISE EXCEPTION 'STEP6A3_PUBLICATION_UNAPPROVED_PAIR';END IF;
END $pre$;
WITH approved(role_code,permission_code) AS(VALUES('EXECUTIVE_BOARD_VIEWER','compliance.framework.read'),('EXECUTIVE_BOARD_VIEWER','platform.membership_reference.read'),('EXECUTIVE_BOARD_VIEWER','privacy.retention_policy_reference.read'),('GRC_MANAGER','compliance.framework.read'),('GRC_MANAGER','platform.membership_reference.read'),('GRC_MANAGER','privacy.retention_policy_reference.read'),('QUALITY_MANAGER','compliance.framework.read'),('QUALITY_MANAGER','platform.membership_reference.read'),('QUALITY_MANAGER','privacy.retention_policy_reference.read'),('COMPLIANCE_MANAGER','compliance.framework.read'),('COMPLIANCE_MANAGER','platform.membership_reference.read'),('COMPLIANCE_MANAGER','privacy.retention_policy_reference.read'),('RISK_MANAGER','platform.membership_reference.read'),('CISO_SECURITY_MANAGER','compliance.framework.read'),('CISO_SECURITY_MANAGER','platform.membership_reference.read'),('CISO_SECURITY_MANAGER','privacy.retention_policy_reference.read'),('AI_GOVERNANCE_MANAGER','compliance.framework.read'),('AI_GOVERNANCE_MANAGER','platform.membership_reference.read'),('AI_GOVERNANCE_MANAGER','privacy.retention_policy_reference.read'),('PRIVACY_MANAGER','compliance.framework.read'),('PRIVACY_MANAGER','platform.membership_reference.read'),('PRIVACY_MANAGER','privacy.retention_policy_reference.read'),('LEGAL_REVIEWER','compliance.framework.read'),('LEGAL_REVIEWER','platform.membership_reference.read'),('LEGAL_REVIEWER','privacy.retention_policy_reference.read'),('AUDITOR_LEAD','compliance.framework.read'),('AUDITOR_LEAD','platform.membership_reference.read'),('AUDITOR_LEAD','privacy.retention_policy_reference.read'),('AUDITOR','compliance.framework.read'),('AUDITOR','platform.membership_reference.read'),('AUDITOR','privacy.retention_policy_reference.read'),('PROCESS_OWNER','platform.membership_reference.read'),('CONTROL_OWNER','platform.membership_reference.read'),('CONTROL_OWNER','privacy.retention_policy_reference.read'),('EVIDENCE_OWNER','platform.membership_reference.read'),('EVIDENCE_OWNER','privacy.retention_policy_reference.read'),('ACTION_OWNER','platform.membership_reference.read'),('REGULATORY_CONTENT_STEWARD','compliance.framework.read'),('REPORT_VIEWER','compliance.framework.read'),('REPORT_VIEWER','platform.membership_reference.read'),('REPORT_VIEWER','privacy.retention_policy_reference.read'),('VIEWER','compliance.framework.read'),('VIEWER','platform.membership_reference.read'),('VIEWER','privacy.retention_policy_reference.read')), source AS(
 SELECT rp.*,r.role_code,p.permission_code,(substr(stamp.hex,1,8)||'-'||substr(stamp.hex,9,4)||'-7'||substr(entropy.hex,1,3)||'-8'||substr(entropy.hex,4,3)||'-'||substr(entropy.hex,7,12))::uuid AS audit_id
 FROM iam.role_permissions rp JOIN iam.roles r USING(role_id) JOIN iam.permissions p USING(permission_id) JOIN approved e ON e.role_code=r.role_code AND e.permission_code=p.permission_code
 CROSS JOIN LATERAL(SELECT lpad(to_hex(floor(extract(epoch FROM clock_timestamp())*1000)::bigint),12,'0') AS hex) stamp
 CROSS JOIN LATERAL(SELECT md5(gen_random_uuid()::text||rp.role_permission_id::text) AS hex) entropy
), material AS(
 SELECT *,jsonb_build_object('present',true,'role_id',role_id,'role_code',role_code,'permission_id',permission_id,'permission_code',permission_code) AS grant_state FROM source
)
INSERT INTO ops_audit.audit_events(audit_event_id,ownership_class,tenant_id,correlation_id,event_code,event_version,aggregate_type,aggregate_id,command_code,actor_service_principal_id,occurred_at,outcome,before_payload,after_payload,classification)
SELECT audit_id,ownership_class,tenant_id,audit_id,'audit.iam.role_permission.publish.v1',1,'RolePermission',role_permission_id,'phase6a3RolePermissionPublication',current_setting('tcdx.publication_service_principal_id')::uuid,clock_timestamp(),'success',grant_state,
 grant_state||jsonb_build_object('manifest_sha256','7462a780d4e0afe23c812983b762685e6f1aa8944ddef85afc50ca2c6d01cd72','receipt_sha256','eed714be808cf63ea5b32c750fa003336851bb6545044a9fe051ed1c053334b1','migration_id','20261009000300','source_migration_id','20261009000200','source_migration_sha256','920ececb9d28e3821a9faf9d2c754db481a26c0e33c53ae0f94b3a0535885ed8','reason','Exact macro R2 governed adoption; preexisting presence preserved'), 'restricted'
FROM material WHERE NOT EXISTS(SELECT 1 FROM ops_audit.audit_events a WHERE a.aggregate_type='RolePermission' AND a.aggregate_id=material.role_permission_id AND a.event_code='audit.iam.role_permission.publish.v1' AND a.command_code='phase6a3RolePermissionPublication' AND a.tenant_id IS NOT DISTINCT FROM material.tenant_id AND a.after_payload->>'migration_id'='20261009000300');
DO $post$ BEGIN
 IF EXISTS(SELECT 1 FROM iam.role_permissions rp JOIN iam.permissions p USING(permission_id) WHERE p.permission_code IN('compliance.framework.read','platform.membership_reference.read','privacy.retention_policy_reference.read') AND NOT EXISTS(SELECT 1 FROM ops_audit.audit_events a WHERE a.event_code='audit.iam.role_permission.publish.v1' AND a.aggregate_type='RolePermission' AND a.aggregate_id=rp.role_permission_id AND a.tenant_id IS NOT DISTINCT FROM rp.tenant_id AND a.ownership_class=rp.ownership_class AND a.outcome='success' AND a.before_payload->>'present'='true' AND a.after_payload->>'present'='true' AND a.after_payload->>'manifest_sha256'='7462a780d4e0afe23c812983b762685e6f1aa8944ddef85afc50ca2c6d01cd72' AND a.after_payload->>'receipt_sha256'='eed714be808cf63ea5b32c750fa003336851bb6545044a9fe051ed1c053334b1' AND a.after_payload->>'source_migration_sha256'='920ececb9d28e3821a9faf9d2c754db481a26c0e33c53ae0f94b3a0535885ed8')) THEN RAISE EXCEPTION 'STEP6A3_PUBLICATION_AUDIT_INCOMPLETE';END IF;
END $post$;
